(85, 2, 'เครื่องคัดแยกเมล็ดข้าวสาร', '&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/ebf891fff245d5072c52207abf06ee63.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/f18737f537ba46c1d3ebf88557772233.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/c11388ed4ea4d8c6ae7f6948f797e18c.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/cf0becc6c23cfe3dcf770818fbd49420.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/d397bfeb79b74b9022a7651499ad96ae.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/9ZP2/f99ad0ecd3e3bef74f4d9056bf46dbcc.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/LM-MMA300/เครื่องอัดฉีดเบนซิน-05.jpg&quot; style=&quot;width: 100%;&quot;&gt;&lt;span style=&quot;font-size: 14px;&quot;&gt;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;&lt;p&gt;&lt;img src=&quot;http://ford.orangeworkshop.info/landmart/upload/image/catalog/LM-MMA300/b7d9318f4e88e6fb7a52af7cd20b7b62.jpeg&quot; style=&quot;width: 100%;&quot;&gt;&lt;/p&gt;&lt;p&gt;&lt;span